pub fn findLegacy(name: []const u8) ?Encoding {
    var low: usize = 0;
    var high = legacy_aliases.len;
    while (low < high) {
        const middle = low + (high - low) / 2;
        switch (std.mem.order(u8, legacy_aliases[middle].name, name)) {
            .lt => low = middle + 1,
            .gt => high = middle,
            .eq => return legacy_encodings[legacy_aliases[middle].encoding],
        }
    }
    return null;
}

pub fn findSingleByte(name: []const u8) ?SingleByteEncoding {
    var low: usize = 0;
    var high = single_byte_aliases.len;
    while (low < high) {
        const middle = low + (high - low) / 2;
        switch (std.mem.order(u8, single_byte_aliases[middle].name, name)) {
            .lt => low = middle + 1,
            .gt => high = middle,
            .eq => return single_byte_encodings[single_byte_aliases[middle].encoding],
        }
    }
    return null;
}
